"use client";
import {useEffect,useState} from "react";
import {prompts} from "./hub-data";
import {Icon} from "./hub-ui";
type P=typeof prompts[number];
export default function PromptLibrary(){
const [extras,setExtras]=useState<P[]>([]),[filter,setFilter]=useState("All"),[q,setQ]=useState(""),[creating,setCreating]=useState(false),[name,setName]=useState(""),[body,setBody]=useState(""),[notice,setNotice]=useState("");
useEffect(()=>{try{const saved=JSON.parse(localStorage.getItem("nbo-custom-prompts")||"[]");if(Array.isArray(saved))setExtras(saved)}catch{}},[]);
const copy=async(text:string)=>{try{await navigator.clipboard.writeText(text);setNotice("Copied to clipboard")}catch{setNotice("Browser clipboard permission required")}};
const save=()=>{if(!name.trim()||!body.trim()){setNotice("Enter a title and prompt");return}const next=[...extras,{name:name.trim(),text:body.trim(),cat:"Mine",desc:"Saved in this browser"}];setExtras(next);localStorage.setItem("nbo-custom-prompts",JSON.stringify(next));setCreating(false);setName("");setBody("");setNotice("Saved on this device")};
const remove=(index:number)=>{const next=extras.filter((_,i)=>i!==index);setExtras(next);localStorage.setItem("nbo-custom-prompts",JSON.stringify(next));setNotice("Removed from this device")};
const all=[...prompts,...extras].filter(p=>(filter==="All"||p.cat===filter)&&(p.name+" "+p.desc+" "+p.text).toLowerCase().includes(q.toLowerCase()));
return <><div className="toolbar"><label className="search"><Icon name="search"/><input aria-label="Search prompts" value={q} onChange={e=>setQ(e.target.value)} placeholder="Search prompt library…"/></label><button className="btn primary" onClick={()=>setCreating(v=>!v)}><Icon name={creating?"close":"plus"}/>{creating?"Cancel":"Add prompt"}</button></div>{creating&&<section className="panel"><h2>Your new prompt</h2><p className="muted">Personal prompts are saved only in this browser.</p><input className="field" value={name} onChange={e=>setName(e.target.value)} placeholder="Prompt title"/><textarea className="field" rows={5} value={body} onChange={e=>setBody(e.target.value)} placeholder="Write your reusable prompt…"/><button className="btn primary" onClick={save}>Save prompt</button></section>}<div className="filters">{["All","Planning","Development","Quality","Mine"].map(f=><button key={f} onClick={()=>setFilter(f)} className={filter===f?"chosen":""}>{f}</button>)}</div><div className="prompt-grid">{all.map((p,i)=><article className="prompt-card" key={p.name+i}><div className="card-top"><span className="tile-icon"><Icon name="Prompts"/></span><span className="muted small">{p.cat}</span></div><h2>{p.name}</h2><p>{p.desc}</p><details><summary>Read full prompt</summary><pre>{p.text}</pre></details><button className="btn secondary" onClick={()=>void copy(p.text)}><Icon name="copy"/> Copy prompt</button>{p.cat==="Mine"&&<button className="delete" onClick={()=>remove(extras.indexOf(p))}>Remove saved prompt</button>}</article>)}{!all.length&&<p className="muted">No matching prompts.</p>}</div>{notice&&<div className="toast" role="status">{notice}</div>}</>;
}